package com.arjunren.leave.service;
import com.arjunren.leave.domain.*;import com.arjunren.leave.dto.Dtos.*;import com.arjunren.leave.entity.*;import com.arjunren.leave.exception.DomainException;import com.arjunren.leave.repository.*;import java.time.*;import java.time.temporal.ChronoUnit;import java.util.*;import org.springframework.data.domain.*;import org.springframework.http.HttpStatus;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class LeaveService{private final UserRepository users;private final EmployeeProfileRepository employees;private final LeaveRequestRepository leaves;private final PasswordEncoder encoder;public LeaveService(UserRepository u,EmployeeProfileRepository e,LeaveRequestRepository l,PasswordEncoder p){users=u;employees=e;leaves=l;encoder=p;}@Transactional public EmployeeResponse createEmployee(EmployeeCreate r,AppUser actor){if(actor.getRole()!=Role.ADMIN)throw forbidden("Admin role required");if(r.role()!=Role.EMPLOYEE&&r.role()!=Role.MANAGER)throw new DomainException(HttpStatus.UNPROCESSABLE_ENTITY,"Role must be EMPLOYEE or MANAGER");String email=r.email().trim().toLowerCase(Locale.ROOT);if(users.findByEmailIgnoreCase(email).isPresent())throw new DomainException(HttpStatus.CONFLICT,"Email already exists");AppUser manager=null;if(r.managerId()!=null){manager=users.findById(r.managerId()).filter(x->x.getRole()==Role.MANAGER).orElseThrow(()->new DomainException(HttpStatus.UNPROCESSABLE_ENTITY,"managerId must reference a manager"));}var u=users.save(new AppUser(email,encoder.encode(r.password()),r.name().trim(),r.role()));return EmployeeResponse.of(employees.save(new EmployeeProfile(r.employeeNumber().trim().toUpperCase(Locale.ROOT),u,manager,r.department().trim(),r.annualBalance(),r.sickBalance())));}@Transactional(readOnly=true)public PageResponse<EmployeeResponse>employees(AppUser actor,int page,int size){Pageable p=PageRequest.of(page,size,Sort.by("employeeNumber"));Page<EmployeeProfile>x=actor.getRole()==Role.ADMIN?employees.findAll(p):actor.getRole()==Role.MANAGER?employees.findByManagerId(actor.getId(),p):throwForbidden();return new PageResponse<>(x.map(EmployeeResponse::of).getContent(),page,size,x.getTotalElements(),x.getTotalPages());}@Transactional public LeaveResponse request(LeaveCreate r,AppUser actor){var e=employees.findByUserId(actor.getId()).orElseThrow(()->forbidden("Employee profile required"));if(r.startDate().isBefore(LocalDate.now())||r.endDate().isBefore(r.startDate()))throw new DomainException(HttpStatus.UNPROCESSABLE_ENTITY,"Leave dates must be valid and not in the past");int days=Math.toIntExact(ChronoUnit.DAYS.between(r.startDate(),r.endDate())+1);if(days>30)throw new DomainException(HttpStatus.UNPROCESSABLE_ENTITY,"A request cannot exceed 30 days");if(leaves.hasOverlap(e.getId(),List.of(LeaveStatus.PENDING,LeaveStatus.APPROVED),r.startDate(),r.endDate()))throw new DomainException(HttpStatus.CONFLICT,"Leave overlaps an existing request");return LeaveResponse.of(leaves.save(new LeaveRequest(e,r.type(),r.startDate(),r.endDate(),days,r.reason().trim())));}@Transactional(readOnly=true)public PageResponse<LeaveResponse>list(AppUser actor,LeaveStatus status,int page,int size){Pageable p=PageRequest.of(page,size,Sort.by(Sort.Direction.DESC,"createdAt"));Page<LeaveRequest>x;if(actor.getRole()==Role.EMPLOYEE)x=leaves.findByEmployeeUserId(actor.getId(),p);else if(actor.getRole()==Role.MANAGER)x=leaves.findByEmployeeManagerId(actor.getId(),p);else x=status==null?leaves.findAll(p):leaves.findByStatus(status,p);return new PageResponse<>(x.map(LeaveResponse::of).getContent(),page,size,x.getTotalElements(),x.getTotalPages());}@Transactional public LeaveResponse approve(Long id,String note,AppUser actor){var l=lockVisible(id,actor,true);requirePending(l);var e=employees.findByIdForUpdate(l.getEmployee().getId()).orElseThrow();if(l.getType()==LeaveType.ANNUAL){if(e.getAnnualBalance()<l.getTotalDays())throw new DomainException(HttpStatus.CONFLICT,"Insufficient annual leave balance");e.useAnnual(l.getTotalDays());}else if(l.getType()==LeaveType.SICK){if(e.getSickBalance()<l.getTotalDays())throw new DomainException(HttpStatus.CONFLICT,"Insufficient sick leave balance");e.useSick(l.getTotalDays());}l.approve(actor,note);return LeaveResponse.of(l);}@Transactional public LeaveResponse reject(Long id,String note,AppUser actor){var l=lockVisible(id,actor,true);requirePending(l);l.reject(actor,note);return LeaveResponse.of(l);}@Transactional public LeaveResponse cancel(Long id,AppUser actor){var l=lockVisible(id,actor,false);if(!l.getEmployee().getUser().getId().equals(actor.getId()))throw forbidden("Only the employee can cancel this request");requirePending(l);l.cancel();return LeaveResponse.of(l);}public long count(LeaveStatus s){return leaves.countByStatus(s);}private LeaveRequest lockVisible(Long id,AppUser actor,boolean reviewing){var l=leaves.findByIdForUpdate(id).orElseThrow(()->new DomainException(HttpStatus.NOT_FOUND,"Leave request not found"));var manager=l.getEmployee().getManager();if(reviewing){if(actor.getRole()!=Role.ADMIN&&(actor.getRole()!=Role.MANAGER||manager==null||!manager.getId().equals(actor.getId())))throw forbidden("Cannot review this employee's request");}else if(actor.getRole()==Role.EMPLOYEE&&!l.getEmployee().getUser().getId().equals(actor.getId()))throw forbidden("Cannot access another employee's request");return l;}private void requirePending(LeaveRequest l){if(l.getStatus()!=LeaveStatus.PENDING)throw new DomainException(HttpStatus.CONFLICT,"Leave request must be pending");}private DomainException forbidden(String m){return new DomainException(HttpStatus.FORBIDDEN,m);}private Page<EmployeeProfile>throwForbidden(){throw forbidden("Manager or admin role required");}}

